-- Rollback-only accession-intent-v1 SQL/application parity vectors. NOT RUN here.
-- Named golden and unicode-control vectors match intent.test.ts. This independent
-- fixture-local serializer uses PostgreSQL scalar escaping, compact array joins
-- and UTF-8 byte sorting, never jsonb_out array spacing or app-generated bytes.
-- Execute only in a separately authorized home-server session. No production
-- helper/migration, business writes, source retention or runtime parity claim.
\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
BEGIN;
SET LOCAL statement_timeout = '30s';
SET LOCAL standard_conforming_strings = on;
SET LOCAL search_path TO public, pg_temp;

CREATE FUNCTION pg_temp.assert_intent(p_condition BOOLEAN, p_message TEXT)
RETURNS VOID LANGUAGE plpgsql AS $$
BEGIN
    IF p_condition IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'intent assertion failed: %', p_message; END IF;
END;
$$;

CREATE FUNCTION pg_temp.intent_json(p_value JSONB)
RETURNS TEXT LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE v_result TEXT;
BEGIN
    IF jsonb_typeof(p_value) IN ('string', 'null') THEN RETURN p_value::TEXT; END IF;
    IF jsonb_typeof(p_value) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'fixture accepts tuples/scalars only'; END IF;
    SELECT '[' || COALESCE(string_agg(pg_temp.intent_json(value), ',' ORDER BY ordinal), '') || ']'
    INTO v_result FROM jsonb_array_elements(p_value) WITH ORDINALITY AS item(value, ordinal);
    RETURN v_result;
END;
$$;

CREATE FUNCTION pg_temp.canonical_intent(p_clients JSONB)
RETURNS TEXT LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE v_client JSONB; v_samples JSONB; v_clients JSONB := '[]';
BEGIN
    FOR v_client IN SELECT value FROM jsonb_array_elements(p_clients) LOOP
        SELECT jsonb_agg(sample ORDER BY convert_to(pg_temp.intent_json(sample), 'UTF8')) INTO v_samples
        FROM (
            SELECT jsonb_build_array(value->0, value->1, (
                SELECT jsonb_agg(assay.value ORDER BY convert_to(assay.value #>> '{}', 'UTF8'))
                FROM jsonb_array_elements(value->2) AS assay(value)
            )) AS sample FROM jsonb_array_elements(v_client->9)
        ) AS samples;
        v_clients := v_clients || jsonb_build_array((v_client - 9) || jsonb_build_array(v_samples));
    END LOOP;
    SELECT jsonb_agg(value ORDER BY convert_to(pg_temp.intent_json(value), 'UTF8')) INTO v_clients
    FROM jsonb_array_elements(v_clients);
    RETURN pg_temp.intent_json(v_clients);
END;
$$;

DO $vectors$
DECLARE
    v_input JSONB;
    v_canonical TEXT;
    v_expected TEXT;
    v_rebound JSONB;
    v_control TEXT := '"' || E'\\' || chr(8) || chr(12) || E'\n\r\t' || chr(1) || U&'\2028\2029';
    v_escaped_control TEXT := $json$"\"\\\b\f\n\r\t\u0001$json$ || U&'\2028\2029' || $json$"$json$;
BEGIN
    -- golden: independently normalize with 215 SQL authority, then compare exact
    -- compact bytes and the approved fixed digest (no pgcrypto dependency).
    v_input := jsonb_build_array(jsonb_build_array(public.normalize_client_name_v1('  An  '), '2000-01-01',
        NULL, NULL, 'Nam', public.normalize_client_phone_v1('+84901234567'), NULL, NULL, NULL,
        jsonb_build_array(jsonb_build_array('ST-DEMO', 'acceptable', jsonb_build_array('CT-000001')))));
    v_expected := '[["an","2000-01-01",null,null,"Nam","0901234567",null,null,null,[["ST-DEMO","acceptable",["CT-000001"]]]]]';
    v_canonical := pg_temp.canonical_intent(v_input);
    PERFORM pg_temp.assert_intent(convert_to(v_canonical, 'UTF8') = convert_to(v_expected, 'UTF8'), 'golden canonical bytes');
    PERFORM pg_temp.assert_intent(encode(sha256(convert_to('lims-lite:bulk-accession:intent:v1' || chr(10) || v_canonical, 'UTF8')), 'hex')
        = '090da05ce3b97394845d98b5d3fde180f150b3d452b5f067155466859a4e908e', 'golden SHA-256');

    -- unicode-control: U+E000 precedes U+10000 in UTF-8 byte order; ECMAScript
    -- escaping preserves valid Unicode, including U+2028/U+2029, without BOM/LF.
    v_input := jsonb_build_array(
        jsonb_build_array(U&'\+010000', '2000-01-01', NULL, NULL, 'Nam', '0901234567', v_control, NULL, NULL,
            jsonb_build_array(jsonb_build_array('ST-DEMO', 'acceptable', jsonb_build_array('CT-000001')))),
        jsonb_build_array(U&'\E000', '2000-01-01', NULL, NULL, 'Nam', '0901234568', NULL, NULL, NULL,
            jsonb_build_array(jsonb_build_array('ST-OTHER', 'acceptable', jsonb_build_array('CT-000002')))));
    v_expected := '[["' || U&'\E000' || '","2000-01-01",null,null,"Nam","0901234568",null,null,null,[["ST-OTHER","acceptable",["CT-000002"]]]],["'
        || U&'\+010000' || '","2000-01-01",null,null,"Nam","0901234567",' || v_escaped_control
        || ',null,null,[["ST-DEMO","acceptable",["CT-000001"]]]]]';
    v_canonical := pg_temp.canonical_intent(v_input);
    PERFORM pg_temp.assert_intent(convert_to(v_canonical, 'UTF8') = convert_to(v_expected, 'UTF8')
        AND octet_length(v_canonical) = 239, 'unicode-control canonical bytes');
    PERFORM pg_temp.assert_intent(encode(sha256(convert_to('lims-lite:bulk-accession:intent:v1' || chr(10) || v_canonical, 'UTF8')), 'hex')
        = '6ef396284f59ca65aa652936439faffc4406111fb34f3fa99de59a8bbfc72b5d', 'unicode-control SHA-256');
    PERFORM pg_temp.assert_intent(pg_temp.canonical_intent(jsonb_build_array(v_input->1, v_input->0)) = v_canonical, 'client permutation independence');

    -- Same independent fixtures cover nested assay/sample ordering, graph edges
    -- and multiplicity, rather than independently sorting three worksheet lists.
    v_input := '[["an","2000-01-01",null,null,"Nam","0901234567",null,null,null,[["ST-Z","acceptable",["CT-000003","CT-000001"]],["ST-A","acceptable",["CT-000002"]]]]]';
    v_expected := '[["an","2000-01-01",null,null,"Nam","0901234567",null,null,null,[["ST-A","acceptable",["CT-000002"]],["ST-Z","acceptable",["CT-000001","CT-000003"]]]]]';
    PERFORM pg_temp.assert_intent(pg_temp.canonical_intent(v_input) = v_expected, 'nested assignment/sample byte sorting');
    v_input := '[["an","2000-01-01",null,null,"Nam","0901234567",null,null,null,[["ST-DEMO","acceptable",["CT-000001"]],["ST-DEMO","acceptable",["CT-000001"]]]]]';
    PERFORM pg_temp.assert_intent(pg_temp.canonical_intent(v_input) <> v_input::TEXT, 'canonical arrays do not use jsonb_out spacing');
    PERFORM pg_temp.assert_intent(jsonb_array_length(pg_temp.canonical_intent(v_input)::JSONB->0->9) = 2, 'identical sample multiplicity');
    v_input := '[["an","2000-01-01",null,null,"Nam","0901234567",null,null,null,[["ST-A","acceptable",["CT-000001"]]]],["binh","2000-01-01",null,null,"Nam","0901234568",null,null,null,[["ST-B","acceptable",["CT-000002"]]]]]';
    v_rebound := jsonb_set(jsonb_set(v_input, '{0,9}', v_input->1->9), '{1,9}', v_input->0->9);
    PERFORM pg_temp.assert_intent(pg_temp.canonical_intent(v_input) <> pg_temp.canonical_intent(v_rebound), 'rebound distinct samples preserve client edges');
    PERFORM pg_temp.assert_intent(public.normalize_client_name_v1(U&'  NGUY\1EC4N   TH\1ECA AN  ') = 'nguyễn thị an'
        AND public.normalize_client_government_identity_v1('001234567890') = '001234567890', 'accent-preserving SQL name and leading-zero identity parity');
END;
$vectors$;
ROLLBACK;
